import numpy as np
from scipy.stats import spearmanr


def pli_ave(per_ligand_scores):
    """plinder.eval reference aggregation: skip unassigned ligands."""
    assigned = [s for s in per_ligand_scores if s is not None]
    return float(np.mean(assigned)) if assigned else float("nan")


def cg_pli(per_ligand_scores, pb_valid):
    """Coverage-gated, validity-gated PLI.

    per_ligand_scores: one entry per *reference* ligand, None when the
        predictor produced no assignable pose for it.
    pb_valid: matching PoseBusters verdicts; None entries count invalid.
    """
    n_ref = len(per_ligand_scores)
    if n_ref == 0:
        return float("nan")
    total = 0.0
    for s, v in zip(per_ligand_scores, pb_valid):
        if s is None or not v:
            continue  # unassigned or physically invalid -> contributes 0
        total += s
    return total / n_ref


def rank_fidelity(metric_by_predictor, a_priori_order):
    """Spearman between a metric's ordering and the known quality ordering."""
    names = [n for n in a_priori_order if n in metric_by_predictor]
    truth = [-i for i, _ in enumerate(names)]  # first = best
    got = [metric_by_predictor[n] for n in names]
    return float(spearmanr(truth, got).statistic)
